args.query:
SELECT COUNT(*) AS employee_count
FROM dim_employees
WHERE employed_from <= '2026-06-30' AND (employed_to IS NULL OR employed_to >= '2026-04-01');

SELECT SUM(value_moments) AS total_value_moments, SUM(app_opens) AS total_app_opens, COUNT(DISTINCT user_id) AS active_users
FROM fct_user_days
WHERE week = DATE '2026-07-06' AND is_internal = FALSE;

SELECT SUM(value) AS total_mrr
FROM (
  SELECT (392.45499999999987) AS value UNION ALL
  SELECT (510.3041666666666) UNION ALL
  SELECT (750.8849999999999)
) t;

SELECT COUNT(*) AS employees
FROM dim_employees
WHERE active_date <= '2026-06-30' AND (termination_date IS NULL OR termination_date > '2026-04-01');
